<?php
declare(strict_types=1);
namespace Liberu\Accounting\PurchaseRequisitionsApi\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Routing\Controller;use Liberu\Accounting\PurchaseRequisitions\Actions\{CreateRequisition,RecordApproval,TransitionRequisition};use Liberu\Accounting\PurchaseRequisitions\Enums\RequisitionStatus;use Liberu\Accounting\PurchaseRequisitions\Models\PurchaseRequisition;
final class PurchaseRequisitionsController extends Controller {public function index():mixed{return PurchaseRequisition::query()->with('approvals')->latest()->paginate(25);}public function store(Request $request,CreateRequisition $action):PurchaseRequisition{return $action->handle($request->validate(['team_id'=>'nullable|integer','requester_ref'=>'required|string','title'=>'nullable|string','currency'=>'required|string|size:3','total_amount'=>'required|numeric|min:0.01','lines'=>'required|array|min:1','coding'=>'nullable|array','budget'=>'nullable|array','attachments'=>'nullable|array']));}public function show(PurchaseRequisition $requisition):PurchaseRequisition{return $requisition->load('approvals');}public function transition(Request $request,PurchaseRequisition $requisition,TransitionRequisition $action):PurchaseRequisition{$data=$request->validate(['status'=>'required|string','sourcing_ref'=>'nullable|string','converted_ref'=>'nullable|string']);return $action->handle($requisition,RequisitionStatus::from($data['status']),$data);}public function approve(Request $request,PurchaseRequisition $requisition,RecordApproval $action):mixed{return $action->handle($requisition,$request->validate(['approver_ref'=>'required|string','decision'=>'required|string','reason'=>'nullable|string']));}}
